//! Golden rows from the reference tmux 3.8, regenerated by
//! `tests/format_cases.sh` into `golden_rows.in`.

use super::{FormatContext, expand_str};
use std::collections::HashMap;

include!("golden_rows.in");

/// `n` nested true conditionals around `ok`.
fn nest(n: usize) -> String {
    (0..n).fold("ok".to_owned(), |s, _| format!("#{{?@x,{s}}}"))
}

fn r(template: impl Into<String>, expected: impl Into<String>) -> (String, String) {
    (template.into(), expected.into())
}

/// The fixture `format_cases.sh` builds in the reference server.
struct Fixture(HashMap<&'static str, &'static str>);

impl FormatContext for Fixture {
    fn get(&self, name: &str) -> Option<String> {
        self.0.get(name).map(|v| (*v).to_owned())
    }
}

fn fixture() -> Fixture {
    Fixture(HashMap::from([
        ("session_name", "s"),
        ("window_name", "w"),
        ("window_index", "0"),
        ("window_flags", "*"),
        ("pane_index", "0"),
        ("pane_id", "%0"),
        ("pane_title", "t"),
        ("@x", "1"),
        ("@zero", "0"),
        ("@empty", ""),
        ("@name", "hello"),
        ("@loop", "x#{E:@loop}y"),
        ("@cond", "#{?@x,yes,no}"),
        ("@esc", "a#,b"),
    ]))
}

#[test]
fn golden_rows_match_reference() {
    let ctx = fixture();
    let mut failures = Vec::new();
    for (template, expected) in rows() {
        let got = expand_str(&template, &ctx);
        if got != expected {
            failures.push(format!("{template:?}: expected {expected:?}, got {got:?}"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
